// appresso_cafe/orders.py
"""Defines Order class and functions to generate synthetic orders.
Each order has:
- order_id (int)
- client_name (str)
- products (list of (product_name, quantity))
- status (str) one of ['Solicitado', 'En Proceso', 'Entregado']
"""

import random
import string
from typing import List, Tuple

PRODUCTS = ["cafe", "latte", "capuccino", "espresso", "muffin", "tarta"]
STATUSES = ["Solicitado", "En Proceso", "Entregado"]

class Order:
    def __init__(self, order_id: int, client_name: str, products: List[Tuple[str, int]], status: str):
        self.order_id = order_id
        self.client_name = client_name
        self.products = products
        self.status = status

    def total_quantity(self) -> int:
        return sum(q for _, q in self.products)

def _random_name() -> str:
    return "".join(random.choice(string.ascii_uppercase) for _ in range(5))

def _random_products() -> List[Tuple[str, int]]:
    # Random number of different products (1-4)
    num = random.randint(1, 4)
    chosen = random.sample(PRODUCTS, num)
    return [(p, random.randint(1, 5)) for p in chosen]

def generate_orders(n: int) -> List[Order]:
    """Generate a list of *n* synthetic orders."""
    orders: List[Order] = []
    for i in range(1, n + 1):
        orders.append(
            Order(
                order_id=i,
                client_name=_random_name(),
                products=_random_products(),
                status=random.choice(STATUSES),
            )
        )
    return orders

# Core algorithms -----------------------------------------------------------

def find_order_by_id(orders: List[Order], target_id: int, counter) -> Order:
    """Linear search for an order. Counts comparisons via *counter*.
    Returns the order or None if not found.
    """
    for order in orders:
        counter.comparisons += 1
        if order.order_id == target_id:
            return order
    return None

def total_products_processed(orders: List[Order], counter) -> int:
    """Sum of all product quantities across all orders. Counts assignments.
    """
    total = 0
    for order in orders:
        for _, qty in order.products:
            counter.assignments += 1
            total += qty
    return total

def recursive_order_count(orders: List[Order], index: int, counter) -> int:
    """Recursively count total quantity of products.
    *counter* records recursive calls.
    """
    counter.calls += 1
    if index >= len(orders):
        return 0
    current = orders[index].total_quantity()
    return current + recursive_order_count(orders, index + 1, counter)

class OpCounter:
    """Simple operation counter used by algorithms to track primitive operations (comparisons, additions, etc.)."""
    def __init__(self):
        self.count = 0
    def inc(self, n: int = 1):
        self.count += n
    def reset(self):
        self.count = 0
    def get(self) -> int:
        return self.count

from typing import List
from .orders import Order
from .counter import OperationCounter


def find_order_linear(orders: List[Order], target_id: int, counter: OperationCounter) -> Order:
    """Linear search for an order by id. Counts each comparison as an operation."""
    for order in orders:
        counter.comparisons += 1
        if order.order_id == target_id:
            return order
    return None


def total_products(orders: List[Order], counter: OperationCounter) -> int:
    """Sum total quantity of all products across orders. Counts each addition as operation."""
    total = 0
    for order in orders:
        for qty in order.quantities:
            counter.additions += 1
            total += qty
    return total


def recursive_analyze(orders: List[Order], index: int, counter: OperationCounter) -> int:
    """Recursively sum product quantities.
    Each recursive call increments counter.calls and each quantity addition increments counter.additions.
    """
    counter.calls += 1
    if index >= len(orders):
        return 0
    subtotal = 0
    for qty in orders[index].quantities:
        counter.additions += 1
        subtotal += qty
    return subtotal + recursive_analyze(orders, index + 1, counter)

class OperationCounter:
    def __init__(self):
        self.comparisons = 0
        self.assignments = 0
        self.calls = 0

    def reset(self):
        self.comparisons = 0
        self.assignments = 0
        self.calls = 0

    def __repr__(self):
        return f"OperationCounter(comparisons={self.comparisons}, assignments={self.assignments}, calls={self.calls})"

